INSERT INTO `announcements` (`announcement_id`, `content`, `title`, `admin_name`, `created_at`, `image`, `deleted`) VALUES
(37, '🎉 Welcome to Harley!\r\n\r\nWe’re excited to have you on board! This is your go-to spot for updates, time log-ins, leave filing, and Change Work Schedule (CWS) requests.\r\n\r\nStay tuned—more exciting announcements and updates are coming your way soon! 🚀\r\n\r\nCheers,\r\n\r\nHarley', NULL, 'Admin', '2025-07-01 13:56:22', NULL, 0),
(39, 'Hi All,\r\n\r\nMSN! :)\r\n\r\nHappy Friday, everyone!\r\n\r\nCheers,\r\n\r\nHarley', NULL, 'Admin', '2025-07-04 16:01:23', NULL, 0),
(40, 'Hi Team,\r\n\r\nThere have been several major cyber security incidents in the news recently, and we want to take this opportunity to remind everyone to stay vigilant and keep your data secure.\r\n\r\nHere are a few simple ways to avoid security breaches:\r\n\r\n🔐 Use strong, unique passwords and update them regularly\r\n📧 Be cautious of suspicious emails – don’t click on unknown links or attachments\r\n🛑 Avoid downloading unverified software or files\r\n🔄 Keep your systems and software up to date\r\n⚠️ If you\'re about to install a software and WatchGuard flags it, please notify the IT team first so we can check if it\'s safe\r\n🔍 Report anything unusual immediately\r\n\r\nAs always, our IT Team is here to support you. If you think you’ve accidentally downloaded something harmful or noticed signs of malware, please reach out to us right away.\r\n\r\nThank you for helping keep our systems safe!\r\n\r\nBest regards,\r\nIT Team', NULL, 'Admin', '2025-07-09 07:59:52', NULL, 0),
(42, 'Hope you are all safe and dry! ☀️\r\n\r\nWe’ve been experiencing frequent and unpredictable change in our weather lately. With your safety and well-being in mind, we want to keep you informed and prepared.\r\n\r\nAs of July 11, 2025, Friday:\r\nWeather Forecast: Moderate to heavy rainshowers with lightning ⛈️\r\nWind Speed: Light to Moderate 🌬️\r\nAffected Areas: Pampanga, Tarlac, Bulacan, Metro Manila, Cavite, Batangas, Rizal, Laguna and Nueva Ecija \r\n\r\nEmergency Hotlines ☎️ 🚨\r\nAngeles City: 0917-851-9581 or 0998-842- 7746 \r\nCSFP: 0939-936-2423 or 0939-961-4357 \r\nMabalacat City: 0998-999-4357\r\n\r\nIf you’re having trouble getting to work because of the weather, please let your supervisor know as soon as you can. You may reach out via email, chat, or any usual way to communicate. Your safety comes first!', NULL, 'Admin', '2025-07-11 11:02:02', NULL, 0),
(43, 'Hi All,\r\n\r\nJust a quick reminder that our payroll cut-off is tomorrow. Kindly ensure that all adjustments, leave requests, and overtime entries are filed on time, complete with the necessary attachments and approvals.\r\n\r\nPlease note that overtime requests without prior approval will not be processed.\r\n\r\nThank you for your cooperation!\r\n\r\nCheers,\r\nHR', NULL, 'Admin', '2025-07-15 07:24:07', NULL, 0),
(58, 'Hi Team,\r\n\r\nAt approximately 10:38 AM today, July 15, 2025, a magnitude 5.8 earthquake was recorded in Ilocos Norte. Below are the reported intensities in affected areas:\r\n\r\n- Intensity IV – Claveria (Cagayan), San Nicolas & Solsona (Ilocos Norte), Sinait & Vigan City (Ilocos Sur)\r\n- Intensity III – Gonzaga (Cagayan)\r\n- Intensity II – Bangued (Abra), Peñablanca (Cagayan), Narvacan (Ilocos Sur)\r\n- Intensity I – Candon (Ilocos Sur), Ilagan (Isabela)\r\n\r\nWhile we are located far from the epicenter, a mild tremor was still felt in Pampanga.\r\n\r\nOur IT Specialist, Cedrick, has checked in with all team members, and we are glad to report that everyone is safe and no damage has been observed in the building. Nevertheless, we encourage everyone to remain alert and vigilant, especially in case of aftershocks.\r\n\r\nPlease be reminded to take note of the nearest fire exits and follow standard safety protocols at all times.\r\n\r\nStay safe, everyone, and thank you for your cooperation.\r\n\r\nRegards,\r\nHR Department', NULL, 'Admin', '2025-07-15 10:58:18', NULL, 0),
(67, 'Hi All,\n\nJust an update regarding our HMO provider, Cocolife:\n\nWe were informed that some clinics and hospitals are currently on hold due to ongoing reconciliation of claims. This involves discrepancies between the amounts being charged by the facilities and the actual amounts covered by Cocolife. They advised that approximately 75% of these reconciliations are expected to be resolved by August.\n\nIn the meantime, please see the attached updated list of available and alternative clinics/facilities that you may reach out to.\n\nThank you, and rest assured we will continue to monitor this closely with Cocolife.\n\nRegards,\nHR', NULL, 'Admin', '2025-07-15 14:46:17', '[\"uploads\\/file_6875f938f3b7a8.31042859.xlsx\",\"uploads\\/file_6875f938f3e122.16187353.xlsx\",\"uploads\\/file_6875f938f40044.46915340.xlsx\",\"uploads\\/file_6875f939000767.06844388.xlsx\"]', 0),
(74, 'Hi Team,\r\n\r\nThis is a final reminder to review your attendance history and file any necessary adjustments with Harley as soon as possible.\r\n\r\nFor Overtime (OT) submissions, please send them to the HR email with client or Team Lead approval attached.\r\n\r\n🕒 Cut-off for all submissions is tomorrow, July 17, 2025, at 7:00 AM.\r\n\r\nAny late endorsements will be processed on the next payroll cut-off.\r\n\r\nThank you for your strict compliance.\r\n\r\nBest regards,\r\nHR', NULL, 'Admin', '2025-07-16 14:53:43', NULL, 0),
(75, 'Hi Team,\r\n\r\nHappy Friday! We hope everything is going well with you.\r\n\r\nDraft payslips for the July 1–15, 2025 cut-off are scheduled to be released today. If you have any concerns or discrepancies with your payslip computation, please email us using the following subject line: Payroll Dispute.\r\nThis format will also be used for future payroll concerns. Kindly follow this subject line format moving forward.\r\n\r\nThank you!', NULL, 'Admin', '2025-07-18 09:52:32', NULL, 0),
(76, 'Hi All!\r\n\r\nHope you’ve all had a fantastic day! 🎉\r\n\r\nSalaries have been successfully credited to your accounts. Wishing you all a relaxing and enjoyable weekend ahead! 🌞', NULL, 'Admin', '2025-07-18 16:21:07', NULL, 0),
(77, '🌧️ Weather Advisory – Saturday, July 19, 2025\r\n\r\nIt’s a rainy Saturday morning as Typhoon Crising continues to bring inclement weather to the region.\r\n\r\n⚠️ Rainfall Warnings\r\nOrange Rainfall Warning: Zambales, Bataan\r\nYellow Rainfall Warning: Pampanga, Bulacan, Tarlac, Rizal, parts of Laguna, Batangas, Cavite, and Metro Manila\r\n\r\nPampanga Weather Advisory\r\nWeather Forecast: Heavy rains\r\nWind Speed: Moderate to strong \r\nFlooding is possible in low-lying areas and areas near river channels.\r\n\r\n🚨 Emergency Hotlines\r\nAngeles City: 0917-851-9581 / 0998-842-7746\r\nCity of San Fernando (CSFP): 0939-936-2423 / 0939-961-4357\r\nMabalacat City: 0998-999-4357\r\n\r\n📢 Important ReminderIf you\'re having difficulty getting to work due to the weather, please inform your supervisor as soon as possible. You may contact them via email, chat, or your usual communication channel.\r\n\r\nPlease stay safe and take care. Keep yourself updated with the latest weather advisories. 🌂', NULL, 'Admin', '2025-07-19 08:50:33', NULL, 0),
(78, '🌧️ Weather Advisory – Tuesday, July 22, 2025\r\n\r\nAs per the weather advisory of PAGASA, we are experiencing heavy rainfalls due to the Southwest Monsoon (Habagat). \r\n\r\n⚠️ Rainfall Warnings\r\n🔴Red Rainfall Warning\r\nAreas affected: Metro Manila, Bataan and Cavite\r\nSerious flooding expected in flood-prone areas and low-lying areas.\r\n\r\n🟠Orange Rainfall Warning\r\nAreas affected: Pampanga, Zambales, Bulacan, Laguna, Batangas, Cavite, and Rizal\r\nFlooding is threatening in low-lying areas and near river channels.\r\n\r\n🟡Yellow Rainfall Warning\r\nAreas affected: Tarlac, Quezon, and Nueva Ecija\r\nFlooding is possible in low-lying areas and near river channels.\r\n\r\nPampanga Weather Advisory\r\nWeather Forecast: Monsoon rains\r\nWind Speed: Moderate to strong\r\nFlooding is possible in low-lying areas and areas near river channels.\r\n\r\n🚨 Emergency Hotlines\r\nAngeles City: 0917-851-9581 / 0998-842-7746\r\nCity of San Fernando (CSFP): 0939-936-2423 / 0939-961-4357\r\nMabalacat City: 0998-999-4357\r\n\r\n📢 Important Reminder: If you\'re having difficulty getting to work due to the weather, please inform your supervisor as soon as possible. You may contact them via email, chat, or your usual communication channel.\r\n\r\n👕 Dress Code Adjustment\r\nFor your safety and comfort, you may dress down for the time being provided you bring spare clothes to use once you arrive at the office.\r\n\r\nPlease stay safe and take care. Keep yourself updated with the latest weather advisories. ☂️', NULL, 'Admin', '2025-07-22 07:25:22', NULL, 0),
(79, '🌧️ Weather Advisory – Wednesday, July 23, 2025\r\n\r\nAs of yesterday afternoon, the low-pressure area east of Aurora Province has developed into a tropical depression, now named Dante by PAGASA. Tropical Depression Dante is enhancing the Southwest Monsoon (Habagat) and is expected to intensify into a Severe Tropical Storm within the next 12 hours.\r\n\r\n⚠️ Rainfall Warnings\r\n🟠Orange Rainfall Warning\r\nAreas affected: Zamabales and Bataan\r\nFlooding is threatening in low-lying areas and near river channels.\r\n\r\n🟡Yellow Rainfall Warning\r\nAreas affected: Pampanga, Tarlac Laguna, Rizal, Batangas, Cavite, and Metro Manila\r\nFlooding is possible in low-lying areas and near river channels.\r\n\r\nPampanga Weather Advisory\r\nWeather Forecast: Monsoon rains\r\nWind Speed: Moderate to strong\r\nFlooding is possible in low-lying areas and areas near river channels.\r\n\r\n🚨 Emergency Hotlines\r\nAngeles City: 0917-851-9581 / 0998-842-7746\r\nCity of San Fernando (CSFP): 0939-936-2423 / 0939-961-4357\r\nMabalacat City: 0998-999-4357\r\n\r\n📢 Important Reminder: If you\'re having difficulty getting to work due to the weather, please inform your supervisor as soon as possible. You may contact them via email, chat, or your usual communication channel.\r\n\r\n👕 Dress Code Adjustment\r\nFor your safety and comfort, you may dress down for the time being provided you bring spare clothes to use once you arrive at the office.\r\n\r\nPlease stay safe and take care. Keep yourself updated with the latest weather advisories. ☂️', NULL, 'Admin', '2025-07-23 08:03:11', NULL, 0),
(80, '🌧️ Weather Advisory – Thursday, July 24, 2025\r\n\r\nThe Province of Pampanga has been placed under a State of Calamity following continuous heavy rainfall since July 4, 2025, brought about by the southwest monsoon and successive tropical cyclones. The prolonged weather disturbance has caused widespread flooding, significant damage to public infrastructure and private properties, and has severely impacted the livelihoods of residents across the province.\r\n\r\nPampanga Weather Advisory\r\nWeather Forecast: Moderate to strong rainfall\r\nWind Speed: Moderate to strong\r\nFlooding is possible in low-lying areas and areas near river channels.\r\n\r\n⚠️ Rainfall Warnings\r\n🟠Orange Rainfall Warning\r\nAreas affected: Bataan, Metro Manila, Cavite, Batangas, Rizal and Laguna.\r\nFlooding is threatening in low-lying areas and near river channels.\r\n\r\n🟡Yellow Rainfall Warning\r\nAreas affected: Zambales, Tarlac, Pampanga, Bulacan and Quezon.\r\nFlooding is possible in flood-prone areas.\r\n\r\n🚨 Emergency Hotlines\r\nAngeles City: 0917-851-9581 / 0998-842-7746\r\nCity of San Fernando (CSFP): 0939-936-2423 / 0939-961-4357\r\nMabalacat City: 0998-999-4357\r\n\r\n📢 Important Reminder: If you\'re having difficulty getting to work due to the weather, please inform your supervisor as soon as possible. You may contact them via email, chat, or your usual communication channel.\r\n\r\n👕 Dress Code Adjustment\r\nFor your safety and comfort, you may dress down for the time being provided you bring spare clothes to use once you arrive at the office.\r\n\r\nPlease stay safe and take care. Keep yourself updated with the latest weather advisories. ☂️', NULL, 'Admin', '2025-07-24 11:12:33', NULL, 0),
(81, '📢 Important Reminder: If you\'re having difficulty getting to work due to the weather, please inform your supervisor as soon as possible. You may contact them via email, chat, or your usual communication channel. You may also contact the internal team directly using the numbers provided below.\r\n\r\nCedrick Arnigo: 0993-864-2974\r\nRJ Tolomia: 0919-099-3036\r\n\r\nFollowing the declaration of a State of Calamity in Pampanga, you may contact the numbers listed below for any emergency assistance.\r\n\r\n🚨 Emergency Hotlines\r\nAngeles City: 0917-851-9581 / 0998-842-7746\r\nApalit: 0998-180-9077\r\nArayat: 0922-906-2071\r\nBacolor: 0966-136-5586\r\nCandaba: 0915-110-6306\r\nCity of San Fernando (CSFP): 0939-936-2423 / 0939-961-4357\r\nFloridablanca: 0962-126-6282\r\nGuagua: 0999-805-0357\r\nLubao: 0917-812-5607\r\nMabalacat City: 0998-999-4357\r\nMacabebe: 0917-608-6038\r\nMagalang: 0917-146-9432\r\nMasantol: 0906-189-3021\r\nMexico: 0970-824-8622 / 0905-918-7574\r\nMinalin: 0926-500-2119 / 0917-137-8081\r\nPorac: 0929-441-6188 / 0953-694-2079\r\nSan Luis 0948-993-8163\r\nSan Simon 0994-245-5764\r\nSasuan 0961-645-6149\r\nSta. Ana 0997-788-4690\r\nSta. Rita – 0960-341-2399\r\nSto. Tomas: 0917-505-9197', NULL, 'Admin', '2025-07-24 15:31:21', NULL, 0),
(82, 'Happy Hump Day, team!\r\n\r\nFor those who applied for loans, please note that HR will review and approve all loan applications by Friday.\r\n\r\nFor loans that have already been approved, kindly make sure to send your Statement of Account (SOA) to HR as soon as possible.\r\n\r\nThank you! 😊', NULL, 'Admin', '2025-07-30 11:12:26', NULL, 0),
(83, 'Hi, Everyone!\r\n\r\nHope you\'re all having a great day!\r\n\r\nAs we prepare for the upcoming payroll, kindly remind your team members to review their logs and file any necessary requests for:\r\n\r\nIncomplete logs (Time Adjustments)\r\nOvertime\r\nLeaves\r\n\r\nThis will help us avoid any discrepancies or delays in payroll processing.\r\n\r\nThank you for your cooperation!', NULL, 'Admin', '2025-07-30 15:20:37', NULL, 0),
(84, 'Hi everyone!\r\n\r\nWe’re excited to invite you to Engagement Thursday, happening today, July 31, 2025, at the Pantry Area from 12:00 NN to 1:00 PM.\r\n\r\nJoin us as we discuss the new system update on Harley—learn more about the improvements and how they benefit you.\r\n\r\nPlus, enjoy some healthy and nutritious food while you\'re at it!\r\n\r\nSee you there! 😊', NULL, 'Admin', '2025-07-31 09:25:03', NULL, 0),
(85, 'Hi, Everyone! Hope everyone is having a good day. \r\n\r\nMay I kindly request that you check your attendance history on Harley and see if you have any incomplete logs? Please file a request for any discrepancies on or before 2:00 PM today.\r\n\r\nIf you’ve read this message, kindly react with a ❤️. Thank you!', NULL, 'Admin', '2025-08-01 11:25:56', NULL, 0),
(86, 'Hi, Everyone!\r\n\r\nPlease disregard the payday countdown on Harley. Actual payday is scheduled tomorrow.\r\n\r\nThank you!', NULL, 'Admin', '2025-08-04 06:55:39', NULL, 0),
(87, 'Hi Team,\r\n\r\nHappy Monday! 😊\r\n\r\nWe’re pleased to announce that our HMO has been renewed with Cocolife. They are now in the process of printing our new HMO cards.\r\n\r\nIn the meantime, you may still use your existing HMO card, provided you also present the attached Certificate of Coverage (COC).\r\n\r\nThank you, and please refer to our previous post for the list of accredited HMO facilities.\r\n\r\nRegards,\r\nHR Department', NULL, 'Admin', '2025-08-11 11:39:10', '[{\"original\":\"HMO.png\",\"stored\":\"uploads\\/file_689965dee0c340.42544541.png\"}]', 0),
(88, 'Hi Team!\r\n\r\nAs part of our commitment to continuously improve Harley, please be advised that the system will be temporarily unavailable for scheduled maintenance. This will allow us to roll out important updates and enhancements.', NULL, 'Admin', '2025-08-13 12:44:22', NULL, 0),
