(97, 'Hi, Team!\r\n\r\nPlease be informed that the File Request feature on Harley is currently unavailable. If you need to file a leave for today or in the coming days, kindly email HR directly.', 'Harley Leave Request', 'Admin', '2025-08-13 15:48:19', NULL, 0),
(98, 'Good news! Requesting overtime is now simpler. \r\n\r\nYou no longer need a separate OT time in and time out, just clock your time as usual and Harley will do the rest.\r\n\r\nHow it works (step-by-step)\r\n\r\nTime In at your normal start time. \r\n\r\nWork your regular shift as usual.\r\n\r\nIf you’re doing OT, keep working past your regular schedule.\r\n\r\nClock Out when you’re done for the day (including overtime hours).\r\n\r\nHarley will auto-flag the day as OT-eligible if your Time Out is more than 30 minutes after your default end time.\r\n\r\nImportant Rules:\r\n\r\nYou must exceed 30 minutes past your default end time for that day to qualify as OT.\r\nOT requests expire after 5 days, make sure you submit your requests before then.', 'Announcement: New “Harley” Overtime Request UPDATE', 'Admin', '2025-08-14 15:46:07', '[{\"original\":\"1.png\",\"stored\":\"uploads\\/file_689d943f727375.77698651.png\"},{\"original\":\"2.png\",\"stored\":\"uploads\\/file_689d943f72acf7.36919359.png\"}]', 0),
(99, 'Hi, Everyone!\r\n\r\nPlease take a moment to review your attendance logs for the period August 1 to 15 and resolve any issues or discrepancies until 2PM today. This will help us avoid problems during payroll processing.', 'Reminder: Settle Attendance Issues', 'Admin', '2025-08-15 08:19:49', NULL, 1),
(100, 'Hi, Everyone! \r\n\r\nPlease take a moment to review your attendance logs for the period August 1 to 15 and resolve any issues or discrepancies until 12 NOON tomorrow. This will help us avoid problems during payroll processing.', 'Reminder: Settle Attendance Issues (Aug 1–15)', 'Admin', '2025-08-15 15:52:31', NULL, 0);
