INSERT INTO `post_schedule_change_requests` (`id`, `employee_id`, `reason`, `status`, `created_at`, `start_date`, `end_date`, `work_schedule_id`, `current_work_schedule_id`, `attachment_scr`, `notified`, `explanation`) VALUES
(1, 77, 'change schedule', 'Approved', '2025-08-13 08:29:42', '2025-08-13', '2025-11-30', 9, 4, 'scr_689c4cf66175c.png', 0, NULL),
(2, 75, 'Hi. May I request to please change the whole month of August to 8am-4:30pm shift. Apparently, the whole month shift was changed back to 7am-4pm (please see attached file) when the update occurred today and there\'s no option to choose from August 1 as the dates prior to today are frozen already. Thank you.', 'Approved', '2025-08-13 08:21:56', '2025-08-13', '2025-08-31', 9, 4, 'scr_689c4b24a708e.png', 0, NULL),
(3, 89, 'approved work schedule by client 6:30am to 3:00pm', 'Approved', '2025-08-13 22:10:35', '2025-08-14', '2025-08-31', 8, 4, 'scr_689d0d5bb16cf.png', 0, NULL),
(7, 1009, 'bawal 10 to 7 boi', 'Declined', '2025-08-15 05:32:47', '2025-08-15', '2025-08-15', 7, 4, 'scr_689ec67fc4f4e.jpg', 0, 'bawal talaga'),
(8, 52, 'My work schedule is from 9:00 a.m. to 6:00 p.m., Monday to Friday. However, in Harley, it is recorded as 7:00 a.m. to 4:00 p.m., which causes me to be tagged as late. I kindly request that my schedule in Harley be updated to reflect 9:00 a.m. to 6:00 p.m.. Thank you.', 'Declined', '2025-08-14 10:28:30', '2025-08-15', '2025-12-31', 6, 6, 'scr_689dba4eb89a6.png', 0, 'Hi, Ms. Althea! Could you please provide an attachment that shows your schedule is 7AM - 4PM on Harley? On our end, your schedule is 9AM - 6PM.'),
(9, 43, 'FIXED SCHEDULE EVERY WEDNESDAY 7AM-4PM', 'Approved', '2025-08-15 07:19:24', '2025-08-27', '2025-08-27', 4, 5, 'scr_689edf7c99f64.pdf', 0, NULL),
(10, 43, 'FIXED SCHEDULE EVERY WEDNESDAY 7AM-4PM', 'Approved', '2025-08-15 07:18:56', '2025-08-20', '2025-08-20', 4, 5, 'scr_689edf6066d94.pdf', 0, NULL),
(11, 10, 'Day Off Change due to Personal Matters.', 'Approved', '2025-08-15 09:31:56', '2025-08-18', '2025-08-18', 4, 4, 'scr_689efe8cdef57.pdf', 0, NULL);
