(2, 47, '2025-08-01', '06:52:56', NULL, '06:52:00', '16:00:00', 'I forgot to log out. Please see the attached email to our supplier, which shows the date I was in the office', 'Approved', '2025-08-04 08:11:52', 'attach_688ffac8d60902.37719230.png', '2025-08-13 23:18:38', 0, 0),
(3, 80, '2025-08-04', NULL, NULL, '06:00:00', '15:00:00', 'Time In didn\'t go through | Decline Reason: Hi, Milbert! Can you please share with us the approval of your client for this schedule change?', 'Declined', '2025-08-04 13:45:12', 'attach_689048e8227ce1.44205672.png', '2025-08-13 23:21:25', 0, 0),
