(5, 3, '2025-08-05', '06:34:42', NULL, '06:30:00', NULL, 'PC update delays startup when I turn it on.', 'Approved', '2025-08-05 07:34:38', 'attach_6891438ea8bcb0.85594103.png', '2025-08-13 23:23:18', 0, 0),
(6, 68, '2025-08-06', '06:14:47', NULL, '06:00:00', NULL, 'When I turned on my computer and entered my password, the screen went black and then suddenly displayed the message: \'Updates are underway. Please keep your computer on.', 'Approved', '2025-08-06 06:16:47', 'attach_689282cf572036.43714634.jpeg', '2025-08-13 23:25:53', 0, 0),
(7, 13, '2025-08-07', '09:20:12', NULL, '08:00:00', '19:00:00', 'I forgot to time in, but for reference you may cross check it to the time in/out biometrics. Thank you. | Decline Reason: Hi, Rogelio! Can you please provide a proof that you were on time? You may use your web history or client conversation as proof. Moving forward, for any missed logs, please make sure to provide proof. 😊', 'Declined', '2025-08-07 09:25:15', 'attach_6894007b4623c8.13133283.png', '2025-08-13 23:30:06', 0, 0),
(8, 9, '2025-08-07', '16:01:11', '16:01:14', '06:50:00', NULL, 'for some reason it didn\'t proceed my time in and just found out when logging out.', 'Approved', '2025-08-08 06:56:30', 'attach_68952f1ed33f20.62270907.png', '2025-08-13 23:31:00', 0, 0),
(9, 72, '2025-08-11', '07:27:20', '15:59:25', NULL, '16:00:00', 'Click log out early', 'Approved', '2025-08-12 07:24:45', 'attach_689a7bbd91c651.51066693.jpg', '2025-08-13 23:35:48', 0, 0),
(10, 89, '2025-08-12', '06:10:24', NULL, '06:12:00', '15:00:00', 'no log out due to emergency reason, work later beyond shift schedule', 'Approved', '2025-08-13 06:15:18', 'attach_689bbcf6f2c790.95146241.png', '2025-08-13 23:38:33', 0, 0),
(11, 49, '2025-08-09', NULL, NULL, '06:00:00', '12:00:00', 'I forgot to log in to the Harley last Sunday from 6 AM to 12 noon. I’ll make sure it won’t happen again. | Decline Reason: Hi, Julie Anne! This is noted but kindly provide a proof that you were present during that day? You may use your web history or client conversation as proof. Thanks!', 'Declined', '2025-08-13 08:32:39', 'attach_689bdd27db4412.63221058.png', '2025-08-13 23:43:02', 0, 0),
